"""Right-hand strike controller for the G1 bag scene.

Phases (sim seconds): wind up the right arm, swing it fast through the bag, retract to stand.
The centre of mass is held over the feet with ComFeedback; both feet stay planted.
"""

import numpy as np

from sim.g1.control import STAND_QPOS, WholeBody, ComFeedback

# Right fist waypoints (x, y, z) in the world frame.
REST = np.array([-0.008, -0.242, 0.623])  # fist position in the standing pose
WIND = np.array([-0.05, -0.22, 1.00])  # cocked back, at bag height
STRIKE_END = np.array([0.60, -0.15, 1.00])  # follow-through past the bag
T_WIND = 1.0  # time the wind-up is reached
T_STRIKE = 1.25  # time the strike ends
T_BACK = 2.8  # time back at rest
T_DONE = 4.5


def _smooth(a):
    a = float(np.clip(a, 0.0, 1.0))
    return a * a * (3 - 2 * a)


class Controller:
    def reset(self, task):
        self.task = task
        self.done = False
        self.wb = WholeBody()
        self.q = STAND_QPOS.copy()
        self.fb = ComFeedback()
        self.com0 = None
        self.t_start = None

    def _hand(self, t):
        if t < T_WIND:
            a = _smooth(t / T_WIND)
            return REST + a * (WIND - REST)
        if t < T_STRIKE:
            a = (t - T_WIND) / (T_STRIKE - T_WIND)
            return WIND + a * (STRIKE_END - WIND)
        if t < T_BACK:
            a = _smooth((t - T_STRIKE) / (T_BACK - T_STRIKE))
            return STRIKE_END + a * (REST - STRIKE_END)
        return REST

    def act(self, obs):
        t = obs["time"]
        if t >= T_DONE:
            self.done = True
        if self.com0 is None:
            self.com0 = np.array(obs["com"][:2])
        com_wanted = self.com0
        com_target = self.fb.update(com_wanted, obs["com"][:2])
        left = self.wb.points(self.q)["left_foot"]
        right = self.wb.points(self.q)["right_foot"]
        targets = {
            "left_foot": [0.035, 0.119, 0.0],
            "right_foot": [0.035, -0.119, 0.0],
            "com": com_target,
            "right_hand": self._hand(t),
        }
        self.q = self.wb.solve(self.q, targets)
        return list(self.q[7:])

